/**
 * @name Dangerous subprocess usage in uvicorn
 * @description Detects potentially unsafe uses of subprocess or os.exec* that might allow command injection.
 * @kind path-problem
 * @problem.severity error
 * @id py/uvicorn/subprocess-command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SubprocessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      (
        call = API::moduleImport("subprocess").getMember(["Popen", "run", "call", "check_call", "check_output"]).getACall() or
        call = API::moduleImport("os").getMember(["system", "popen", "execl", "execle", "execlp", "execlpe", "execv", "execve", "execvp", "execvpe"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module SubprocessFlow = TaintTracking::Global<SubprocessConfig>;
import SubprocessFlow::PathGraph

from SubprocessFlow::PathNode source, SubprocessFlow::PathNode sink
where SubprocessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches a subprocess command argument at $@.", source.getNode(), "user input"

/**
 * @name Open redirect / unvalidated URL usage in uvicorn
 * @description Detect flows from remote input into URL-building helpers that may cause open redirects.
 * @kind path-problem
 * @problem.severity error
 * @id py/uvicorn/open-redirect
 * @tags security
 *       external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module RedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::builtin("redirect").getACall() and
      sink = call.getArg(0)
    )
  }
}

module RedirectFlow = TaintTracking::Global<RedirectConfig>;
