from RedirectFlow::PathNode source, RedirectFlow::PathNode sink
where RedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted URL flows into redirect() at $@.", source.getNode(), "user input"

/**
 * @name uvicorn config file path usage
 * @description Flags uses of open() on paths derived from environment variables or CLI arguments in uvicorn.config.
 * @kind path-problem
 * @problem.severity warning
 * @id py/uvicorn/file-path-usage
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module FilePathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ExprNode env |
      env.asExpr() instanceof Call and
      env.asExpr().(Call).getFunc().toString() = "os.getenv" and
      source = env
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    )
  }
}

module FilePathFlow = TaintTracking::Global<FilePathConfig>;
import FilePathFlow::PathGraph

from FilePathFlow::PathNode source, FilePathFlow::PathNode sink
where FilePathFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Environment-derived path from $@ flows into file open().", source.getNode(), "env var"

